/**
 * "Cross the Line" - Automatic Descent Version
 *
 * A horizontal threshold line slowly descends from the top to the bottom of the canvas.
 * Particles shift between pale upward motion and colorful turbulent flow.
 * Brightness fades toward the left and right edges, creating a darker side-gradient.
 */

let particles = [];
const maxParticles = 2000;
const activeParticleCount = 1800;

const descentDuration = 30000; // 30 seconds for the line to move from top to bottom
let thresholdY;

function setup() {
  createCanvas(windowWidth, windowHeight);
	  // スクロールバーが出ないようにスタイルを直接書き換える
  let canvas = document.querySelector('canvas');
  canvas.style.display = 'block';
  document.body.style.overflow = 'hidden';
  document.body.style.margin = '0';
  document.body.style.padding = '0';
  colorMode(HSB, 360, 100, 100, 100);

  thresholdY = 0;

  for (let i = 0; i < maxParticles; i++) {
    particles.push(new Particle());
  }

  background(10);
}

function draw() {
  background(0, 0, 0, 8);

  let progress = (millis() % descentDuration) / descentDuration;
  thresholdY = map(progress, 0, 1, 0, height);

  stroke(0, 0, 15, 40);
  strokeWeight(1);
  line(0, thresholdY, width, thresholdY);

  for (let i = 0; i < activeParticleCount; i++) {
    particles[i].update(thresholdY);
    particles[i].display(thresholdY);
  }
}

// 中央は明るく、左右端へ行くほど暗くする
function getSideBrightness(x) {
  let sideAmount = abs(x - width / 2) / (width / 2);
  return lerp(100, 25, sideAmount);
}

class Particle {
  constructor() {
    this.init();
  }

  init() {
    this.pos = createVector(random(width), random(height));
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
    this.maxSpeed = random(2, 6);
    this.hue = random(240, 280);
  }

  update(ty) {
    let force;

    if (this.pos.y > ty) {
      let waveX = map(
        sin(this.pos.y * 0.5 + frameCount * 0.002),
        -1,
        1,
        -4,
        4
      );

      let targetVel = createVector(waveX, -2);
      force = p5.Vector.sub(targetVel, this.vel);
      force.limit(0.2);

      this.vel.add(createVector(0, -0.2));
    } else {
      let n = noise(
        this.pos.x * 0.005,
        this.pos.y * 0.005,
        frameCount * 0.005
      );

      let angle = map(n, 0, 1, -PI * 3.5, PI * 2.5);
      force = p5.Vector.fromAngle(angle);
      force.mult(1.0);

      this.hue = (this.hue + 0.8) % 360;
    }

    this.acc.add(force);
    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.pos.add(this.vel);
    this.acc.mult(0);

    if (this.pos.y < 0) {
      this.pos.y = height;
      this.pos.x = random(width);
    }

    if (this.pos.x < 0) this.pos.x = width;
    if (this.pos.x > width) this.pos.x = 0;
  }

  display(ty) {
    push();

    let brightness = getSideBrightness(this.pos.x);

    if (this.pos.y > ty) {
      stroke(0, 0, brightness, 50);
      strokeWeight(4);
    } else {
      let speed = this.vel.mag();
      stroke(this.hue, 80, brightness, 65);
      strokeWeight(map(speed, 0, this.maxSpeed, 2, 7));
    }

    point(this.pos.x, this.pos.y);

    pop();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  background(10);
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
